function t(n){if(n==null||n==="")return null;const r=typeof n=="number"?n:Number(String(n).replace(/,/g,"").trim());return Number.isFinite(r)?r:null}function o(n,r,l){const u=t(r),e=t(l);if(u==null&&e==null||n==null||String(n).trim()==="")return null;const i=t(n);return i==null?null:u!=null&&i<u||e!=null&&i>e}function f(n,r,l){const u=o(n,r,l);return u==null?null:u?"abnormal":"normal"}function c(n){const r=f(n.measured_value,n.numeric_min,n.numeric_max);return r==null?n:{...n,result:r,remark:r==="normal"?null:n.remark}}function m(n,r){const l=t(n),u=t(r);return l==null&&u==null?"":l!=null&&u!=null?`${l} ~ ${u}`:l!=null?`≥ ${l}`:`≤ ${u}`}export{c as a,m as f,o as i};
